\section{Introduction}

\subsection{The two objects}

Let $\HH = \{z \in \CC : \Ima z > 0\}$ carry the hyperbolic metric $ds = |dz|/\Ima z$, whose
distance satisfies
\[
  \cosh d(z,w) = 1 + \frac{|z-w|^2}{2\,\Ima z\,\Ima w},
\]
whose geodesics are the vertical half-lines and the semicircles orthogonal to $\RR$, and whose
ideal boundary is $\RR \cup \{\infty\}$.

Call a pair of positive integers $(m,n)$ a \emph{Euclid seed} if
\[
  0 < n < m, \qquad \gcd(m,n) = 1, \qquad m+n \ \text{odd},
\]
so that $(m,n) \mapsto (m^2-n^2,\,2mn,\,m^2+n^2)$ is a bijection onto the primitive Pythagorean
triples. Berggren's theorem states that the three maps
\[
  B_1(m,n) = (2m-n,\,m), \qquad B_2(m,n) = (2m+n,\,m), \qquad B_3(m,n) = (m+2n,\,n)
\]
generate every Euclid seed from the root $(2,1)$ exactly once: the seeds form an infinite
ternary tree.

\subsection{The embedding and the phenomenon}

\begin{definition}
For a Euclid seed $(m,n)$ put $z(m,n) = \dfrac{n+i}{m} = \dfrac nm + \dfrac im \in \HH$.
\end{definition}

The map is injective, since $\Ima z = 1/m$ recovers $m$ and $\Rea z = n/m$ then recovers $n$.
Rendering the node set for $m$ up to a few hundred produces sharp pencils of straight lines
radiating from the ideal points $0$ and $1$, weaker pencils near $0.2$, $0.\overline3$ and
$0.5$, no pencil near $0.25$, and a single bright ray into the interior. Every one of these
features is a theorem, and this paper proves them.

\section{Metric background: the radial law}

\begin{theorem}[Exact radial formula]\label{thm:radial}
For $m \ge 1$, $n \ge 0$,
\[
  \cosh d_\HH\big(i,\ z(m,n)\big) = \frac{m^2+n^2+1}{2m} = \frac{c+1}{2m},
  \qquad c = m^2+n^2 .
\]
\end{theorem}

\begin{proof}
With $z=i$, $w=(n+i)/m$ we have $\Ima w = 1/m$ and $|z-w|^2 = (n^2+(m-1)^2)/m^2$, so
$\cosh d = 1 + \frac m2 \cdot \frac{n^2+(m-1)^2}{m^2} = \frac{m^2+n^2+1}{2m}$.
\end{proof}

The hypotenuse thus appears as the numerator of a hyperbolic cosine, although the embedding
used only the ratios $n/m$ and $1/m$.

\begin{theorem}[Logarithmic trajectory law]\label{thm:traj}
For every Euclid seed, $\tfrac12\log c \le d_\HH(i,z(m,n)) \le \tfrac12\log(2(c+1))$; in
particular $|d - \tfrac12\log c| \le \log 2$.
\end{theorem}

\begin{proof}
Since $\cosh$ increases on $[0,\infty)$ and $\cosh(\tfrac12\log c) = (c+1)/(2\sqrt c)$, the
lower bound is $m \le \sqrt c$, i.e. $m^2 \le m^2+n^2$. For the upper bound,
$\cosh d \le e^d \le 2\cosh d$ gives $d \le \log((c+1)/m)$, and $n<m$ forces $2m^2 \ge c+1$,
whence $(c+1)/m \le \sqrt{2(c+1)}$.
\end{proof}

\begin{corollary}
The residual $\rho = d(i,z(m,n)) - \tfrac12\log c$ satisfies $0 \le \rho \le \tfrac12\log 2 +
1/(2c)$: every node lies in a hyperbolic annulus of width $\approx 0.34657$ about the sphere
of radius $\tfrac12\log c$.
\end{corollary}

\begin{theorem}[Exact two-node distance]\label{thm:twonode}
For $m,m' \ge 1$, $n,n' \ge 0$,
\[
  \cosh d_\HH\big(z(m,n),\,z(m',n')\big) = \frac{(nm'-n'm)^2 + m^2 + m'^2}{2mm'} .
\]
\end{theorem}

\begin{proof}
$\Ima z\,\Ima w = 1/(mm')$ and $|z-w|^2 = ((nm'-n'm)^2 + (m'-m)^2)/(m^2m'^2)$; substitute.
\end{proof}

The integer $nm'-n'm$, the \emph{seed cross product}, is the only arithmetic invariant entering
the metric.

\begin{theorem}[Hypercycle theorem]\label{thm:hyper}
Let $\gamma_x$ be the vertical geodesic from $x \in \RR$ to $\infty$ and let $z \in \HH$
satisfy $\Rea z - x = u\,\Ima z$. Then $\sinh d(z,\gamma_x) = |u|$, the infimum being attained
at the point of $\gamma_x$ of height $\Ima(z)\sqrt{1+u^2}$.
\end{theorem}

\begin{proof}
With $w = x+is$ and $y = \Ima z$,
$\cosh d(z,w) = \big((1+u^2)y^2 + s^2\big)/(2ys) \ge \sqrt{1+u^2}$ by AM--GM, with equality iff
$s = y\sqrt{1+u^2}$; and $\cosh d = \sqrt{1+u^2}$ means $\sinh d = |u|$.
\end{proof}

A Euclidean straight line through an ideal point is therefore a \emph{hypercycle}: a curve of
constant hyperbolic distance from a geodesic, and not itself a geodesic unless $u=0$.

\section{Star charges and the geometry of a single ray}

\begin{definition}[Star charge]
For a boundary rational $p/q$ with $q>0$, $\gcd(p,q)=1$, and a node $z(m,n)$, put
$k(p,q;m,n) = qn - pm$.
\end{definition}

\begin{theorem}[Equation of the radial line]\label{thm:line}
For $m,q > 0$, \ $\Rea z(m,n) = \dfrac pq + \dfrac kq \Ima z(m,n)$.
\end{theorem}

\begin{proof}
$\frac nm - \frac pq = \frac{qn-pm}{qm} = \frac kq\cdot\frac1m$.
\end{proof}

So the nodes of a fixed charge at a fixed rational are exactly collinear along one Euclidean
line through $p/q$: the \emph{ray} of charge $k$, of parameter $k/q$.

\begin{corollary}[A ray is a hypercycle]\label{cor:width}
$\sinh d_\HH(z(m,n),\gamma_{p/q}) = |k(p,q;m,n)|/q$. In particular nodes of equal charge are at
equal hyperbolic distance from $\gamma_{p/q}$, so the charge is (up to the factor $q$) the
hyperbolic width of the ray.
\end{corollary}

\begin{lemma}[Charge is a lattice invariant]\label{lem:transl}
$k(p,q;m+tq,\,n+tp) = k(p,q;m,n)$ for all $t$: the integer points of a ray are the lattice
translates of one another by the primitive vector $(q,p)$.
\end{lemma}

\begin{lemma}\label{lem:dvd}
Any common divisor of $m$ and $n$ divides $k(p,q;m,n) = qn-pm$.
\end{lemma}

\begin{theorem}[Unit rays are fully populated]\label{thm:unit}
Let $(m,n)$ be a Euclid seed with $|k(p,q;m,n)|=1$ and $p<q$. Then $(m+2tq,\,n+2tp)$ is a
Euclid seed for every $t \ge 0$.
\end{theorem}

\begin{proof}
Positivity and $n'<m'$ follow from $p<q$. The gcd of the translated pair divides its charge
(Lemma~\ref{lem:dvd}), which is $\pm1$ by Lemma~\ref{lem:transl}. Finally
$(m+2tq)+(n+2tp) = (m+n)+2t(p+q)$ has the parity of $m+n$.
\end{proof}

\begin{theorem}[Cross product along a ray]\label{thm:cross}
$n(m+tq) - (n+tp)m = tk$, hence by Theorem~\ref{thm:twonode}
\[
  \cosh d\big(z(m,n),\,z(m+tq,\,n+tp)\big) = \frac{(tk)^2 + m^2 + (m+tq)^2}{2m(m+tq)} .
\]
\end{theorem}

\begin{theorem}[Steps along a ray tend to zero]\label{thm:steps0}
With $z_j = z(m+2jq,\,n+2jp)$,
\[
  \cosh d(z_j,z_{j+1}) = 1 + \frac{4k^2+4q^2}{2(m+2jq)(m+2jq+2q)} \longrightarrow 1 ,
\]
so $d(z_j,z_{j+1}) \to 0$.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:cross} with $t=2$ at the node $(m+2jq,\,n+2jp)$, whose charge is again
$k$ by Lemma~\ref{lem:transl}. Since $m+2jq \ge 2j+1$, the error term is $O(1/j^2)$;
monotonicity of $\cosh$ transfers this to the distances.
\end{proof}

\begin{theorem}[A ray converges to its ideal tip]\label{thm:tip}
$z_j \to p/q$ in $\CC$.
\end{theorem}

\begin{proof}
$|\Rea z_j - p/q| = |k|/(q(m+2jq))$ by Theorem~\ref{thm:line}, and $\Ima z_j = 1/(m+2jq)$;
both are $O(1/j)$.
\end{proof}

Theorems~\ref{thm:steps0} and~\ref{thm:tip} say that a ray renders as a smooth straight line
gliding into the boundary rather than as a scatter of separated dots: this is the visual
mechanism by which the fans become visible.

\section{Quantisation and realisation: the charge spectrum}

\begin{theorem}[Quantisation at a both-odd rational]\label{thm:quant}
If $p$ and $q$ are both odd and $(m,n)$ is a Euclid seed, then $k(p,q;m,n)$ is odd.
\end{theorem}

\begin{proof}
Modulo $2$: $p \equiv q \equiv 1$ and $m+n\equiv1$, so $k = qn-pm \equiv n+m \equiv 1$.
\end{proof}

Thus at a both-odd rational exactly half of the pencil, the even-charge rays, is empty.

\begin{lemma}[Determinant-one change of variables]\label{lem:sl2}
Suppose $qx-py=1$ with $x,y \in \ZZ$. If $\gcd(A,k)=1$ then $m = qA+yk$ and $n = pA+xk$ are
coprime, and $k(p,q;m,n) = k$, $xm - yn = A$.
\end{lemma}

\begin{proof}
The matrix $\left(\begin{smallmatrix} q & y \\ p & x\end{smallmatrix}\right)$ has determinant
$1$; explicitly, if $uA+vk=1$ then $(ux-vp)m + (vq-uy)n = u(xm-yn)+v(qn-pm) = uA+vk = 1$. The
identities $qn-pm = k(qx-py) = k$ and $xm-yn = A(qx-py) = A$ are direct.
\end{proof}

\begin{theorem}[Realisation of every admissible charge]\label{thm:realise}
Let $0<p<q$ be coprime, let $k \ne 0$ be an integer which is odd in case $p+q$ is even, and let
$B$ be any bound. Then there is a Euclid seed $(m,n)$ with $m>B$ and $k(p,q;m,n)=k$. Hence
every admissible ray carries infinitely many nodes.
\end{theorem}

\begin{proof}
Choose $qx-py=1$, set $T = x+y$, and take $A = (1+kT) + 2k^2 j$ with $j$ large; put
$(m,n) = (qA+yk,\ pA+xk)$. Then $A \equiv 1 \pmod k$, so $\gcd(A,k)=1$ and
Lemma~\ref{lem:sl2} gives coprimality and the charge. For parity, modulo $2$ we have
$m+n \equiv (p+q)A + Tk$ with $A \equiv 1+kT$. If $p+q$ is odd this is $1 + kT + Tk = 1$. If
$p+q$ is even then $p,q$ are both odd and $qx-py=1$ forces $T = x+y$ odd; with $k$ odd,
$(p+q)A+Tk \equiv 0+1 = 1$. Finally, for $j$ large $A>0$ is arbitrarily large, so
$m = qA+yk > B$, $n = pA+xk>0$ and $m-n = (q-p)A + (y-x)k>0$.
\end{proof}

\begin{theorem}[The central ray]\label{thm:central}
Let $0<p<q$ be coprime and $(m,n)$ a Euclid seed. Then $k(p,q;m,n)=0$ iff $(m,n)=(q,p)$. Hence
the central geodesic $\gamma_{p/q}$ carries a node iff $p+q$ is odd, and then exactly one.
\end{theorem}

\begin{proof}
If $qn = pm$ then $q \mid pm$ and $\gcd(p,q)=1$ give $q \mid m$; symmetrically $m \mid q$; so
$m=q$ and $n=p$. The converse is immediate, and $(q,p)$ is a seed iff $p+q$ is odd.
\end{proof}

\begin{theorem}[Charge spectrum]\label{thm:spectrum}
For coprime $0<p<q$, an integer $k$ is the star charge at $p/q$ of some Euclid seed if and only
if $p+q$ is odd or $k$ is odd.
\end{theorem}

\begin{proof}
Necessity: if $p+q$ is even then $p,q$ are both odd and Theorem~\ref{thm:quant} applies.
Sufficiency: for $k \ne 0$ use Theorem~\ref{thm:realise}; for $k=0$ the hypothesis forces $p+q$
odd, and $(q,p)$ is then a seed of charge $0$.
\end{proof}

\section{The resolution law and the visible rationals}

\begin{definition}[Resolution]
For coprime $p \le q$ with $q>0$ set $\gap(p,q) = 1$ if $p+q$ is odd, $\gap(p,q) = 2$ if $p,q$
are both odd, and $\delta(p/q) = \gap(p,q)/q$.
\end{definition}

By Corollary~\ref{cor:width} the quantity $\sinh d(z,\gamma_{p/q}) = |k|/q$ is the natural
angular coordinate of the star at $p/q$.

\begin{theorem}[Resolution law]\label{thm:res}
Let $p$ or $q$ be odd and let $(m_1,n_1),(m_2,n_2)$ be Euclid seeds with $|k_1| \ne |k_2|$.
Then
\[
  \Big|\sinh d(z_1,\gamma_{p/q}) - \sinh d(z_2,\gamma_{p/q})\Big|
  = \frac{\big||k_1|-|k_2|\big|}{q} \ \ge\ \delta(p/q) .
\]
\end{theorem}

\begin{proof}
The equality is Corollary~\ref{cor:width}. If $p+q$ is odd, $\big||k_1|-|k_2|\big|$ is a
nonzero integer. If $p,q$ are both odd, both charges are odd by Theorem~\ref{thm:quant}, so the
difference is a nonzero even integer.
\end{proof}

\begin{theorem}[Sharpness]\label{thm:sharp}
For every coprime $0<p<q$ there are Euclid seeds realising the value $\delta(p/q)$ in
Theorem~\ref{thm:res}.
\end{theorem}

\begin{proof}
Apply Theorem~\ref{thm:realise} with charges $1$ and $1+\gap(p,q)$; both are admissible, and
their $\sinh$-widths are $1/q$ and $(1+\gap)/q$.
\end{proof}

\begin{theorem}[The visible rationals]\label{thm:visible}
For coprime $p \le q$ with $q>0$,
\[
  \delta(p/q) \ \ge\ \tfrac25
  \iff \frac pq \in \Big\{\tfrac01,\ \tfrac15,\ \tfrac13,\ \tfrac12,\ \tfrac35,\ \tfrac11\Big\}.
\]
\end{theorem}

\begin{proof}
$\gap \le 2$ forces $q \le 5$; a finite check gives $\delta(0/1)=1$, $\delta(1/1)=2$,
$\delta(1/2)=1/2$, $\delta(1/3)=2/3$, $\delta(1/5)=\delta(3/5)=2/5$, while
$\delta(2/3)=1/3$, $\delta(1/4)=\delta(3/4)=1/4$ and $\delta(2/5)=\delta(4/5)=1/5$ all fall
short.
\end{proof}

Numerically the list is $0,\,0.2,\,0.\overline3,\,0.5,\,0.6,\,1$: exactly the boundary points
at which fans are visible in a rendered star map, together with the fan at $0.6$ predicted
before it is noticed. The exclusion of $1/4=0.25$ despite $4<5$ is the signature of the parity
law: an even denominator forfeits the factor-two bonus.

\begin{theorem}[Finite visibility hierarchy]\label{thm:finite}
For every $\varepsilon>0$ only finitely many coprime pairs $p \le q$ have
$\delta(p/q) \ge \varepsilon$.
\end{theorem}

\begin{proof}
$\gap \le 2$ forces $q \le 2/\varepsilon$, and then $p \le q$.
\end{proof}

\section{The brightness law: a totient census of a ray}

\begin{definition}[Ray parameter]
Fix Bézout data $qx-py=1$. The \emph{ray parameter} of an integer point $(m,n)$ is
$A = xm-yn$.
\end{definition}

\begin{lemma}[Ray coordinates]\label{lem:raycoord}
With $qx-py=1$ and $k = qn-pm$: \ $m = qA+yk$, \ $n = pA+xk$, \ $m+n = (p+q)A + (x+y)k$.
\end{lemma}

\begin{theorem}[Coprimality in ray coordinates]\label{thm:copray}
$\gcd(m,n)=1 \iff \gcd(A,k)=1$.
\end{theorem}

\begin{proof}
If $um+vn=1$ then $(uq+vp)A+(uy+vx)k = um+vn = 1$ by Lemma~\ref{lem:raycoord}. Conversely if
$uA+vk=1$ then $(ux-vp)m+(vq-uy)n = u(xm-yn)+v(qn-pm) = uA+vk = 1$.
\end{proof}

This is the structural heart of the census: the charge is the only arithmetic obstruction along
a ray, so on the unit rays $k=\pm1$ every lattice point is primitive.

\begin{lemma}[B\'ezout parity at a both-odd star]\label{lem:bez}
If $p,q$ are both odd and $qx-py=1$ then $x+y$ is odd.
\end{lemma}

\begin{proof}
Modulo $2$, $1 = qx-py \equiv x+y$.
\end{proof}

\begin{lemma}[Parity-free regimes]\label{lem:free}
Assume $\gcd(A,k)=1$.
\begin{enumerate}
\item If $p,q$ are both odd and $k$ is odd, then $(p+q)A+(x+y)k$ is odd for every $A$, since
$p+q$ is even and $(x+y)k$ is odd by Lemma~\ref{lem:bez}.
\item If $p+q$ is odd and $k$ is even, then $A$ is odd (else $2 \mid \gcd(A,k)$) and
$(p+q)A+(x+y)k \equiv 1$.
\end{enumerate}
In both cases the only sieve on the ray is $\gcd(A,k)=1$.
\end{lemma}

\begin{lemma}[Mixed regime]\label{lem:mixed}
If $p+q$ and $k$ are both odd, then $(p+q)A+(x+y)k$ is odd iff $A + (x+y)$ is odd, i.e. iff $A$
lies in a single prescribed residue class modulo $2$.
\end{lemma}

\begin{lemma}[Coprime window count]\label{lem:window}
For all $k,a \ge 0$, \ $\#\{A \in [a,a+2k) : \gcd(A,k)=1\} = 2\varphi(k)$.
\end{lemma}

\begin{proof}
Split into two consecutive windows of length $k$; coprimality to $k$ depends only on
$A \bmod k$, and each residue occurs once per window.
\end{proof}

\begin{lemma}[Coprime window count with a parity class]\label{lem:window2}
For odd $k$ and any $a,e$, \
$\#\{A \in [a,a+2k) : \gcd(A,k)=1,\ A \equiv e \ (\mathrm{mod}\ 2)\} = \varphi(k)$.
\end{lemma}

\begin{proof}
Since $k$ is odd, $A \mapsto A$ if $A \equiv e$, else $A \mapsto A+k$, is a bijection from
$\{A \in [a,a+k) : \gcd(A,k)=1\}$ onto the set in question: adding $k$ flips parity and
preserves coprimality with $k$, and the image lies in $[a,a+2k)$.
\end{proof}

\begin{theorem}[Brightness trichotomy]\label{thm:bright}
Fix coprime $p,q$, B\'ezout data $qx-py=1$, and an admissible charge $k \ge 1$. Among the $2k$
consecutive ray parameters $A \in [a,a+2k)$, the number for which $(qA+yk,\ pA+xk)$ is a
Euclid seed equals
\[
\begin{array}{lll}
\text{(i)} & p,q \text{ both odd},\ k \text{ odd:} & 2\varphi(k) \quad \text{(full brightness)},\\
\text{(ii)} & p+q \text{ odd},\ k \text{ even:} & 2\varphi(k) \quad \text{(full brightness)},\\
\text{(iii)} & p+q \text{ odd},\ k \text{ odd:} & \varphi(k) = \varphi(2k) \quad \text{(half brightness)} .
\end{array}
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:copray} the coprimality condition is $\gcd(A,k)=1$. In cases (i) and (ii)
the parity condition is automatic (Lemma~\ref{lem:free}) and Lemma~\ref{lem:window} applies. In
case (iii) the parity condition is the congruence of Lemma~\ref{lem:mixed} and
Lemma~\ref{lem:window2} applies; $\varphi(2k) = \varphi(2)\varphi(k) = \varphi(k)$ for odd $k$.
\end{proof}

\begin{corollary}[Linear density]
A ray has asymptotic density $\varphi(k)/k$ of nodes among its lattice points in the
full-brightness regimes and $\varphi(k)/(2k)$ in the mixed regime. A unit ray at a both-odd
star is completely full; a ray of prime charge $r$ has density $1-1/r$; a ray of charge
$105 = 3\cdot5\cdot7$ has density $\tfrac23\cdot\tfrac45\cdot\tfrac67 \approx 0.457$.
\end{corollary}

\begin{remark}[Conservation of light]
The two laws compensate exactly. At a both-odd star the rays are spaced $2/q$ apart in $\sinh$
and each carries $2\varphi(k)$ nodes per period $2k$; at a mixed-parity star the rays are twice
as finely spaced and each carries half as many. Parity redistributes the node density between
angular resolution and per-ray intensity, without changing the total.
\end{remark}

\section{Why the stars sit at the rationals}

\begin{theorem}[No star at an irrational point]\label{thm:irr}
Let $\alpha$ be irrational and $c \in \RR$, and suppose $z(m,n)$ and $z(m',n')$ both satisfy
$\Rea z = \alpha + c\,\Ima z$. Then $(m,n) = (m',n')$.
\end{theorem}

\begin{proof}
The hypotheses read $n = \alpha m + c$ and $n' = \alpha m' + c$, so $\alpha(m-m') = n-n'$. If
$m \ne m'$ then $\alpha = (n-n')/(m-m') \in \QQ$, a contradiction; hence $m=m'$ and $n=n'$.
\end{proof}

Irrational boundary points are nevertheless limits of the node set: for any $t \in [0,1]$ and
any large $K$, the pair $(2^K,n)$ with $n$ the odd integer nearest $t\,2^K$ is a Euclid seed
with $n/2^K \to t$. Density without collinearity: an irrational tip carries no fan.

On slopes $t = n/m$ the three moves act by
\[
  B_1 : t \mapsto \frac1{2-t}, \qquad B_2 : t \mapsto \frac1{2+t},
  \qquad B_3 : t \mapsto \frac{t}{1+2t},
\]
with pairwise disjoint images $(\tfrac12,1)$, $(\tfrac13,\tfrac12)$, $(0,\tfrac13)$ --- a
trichotomy which inverts the tree and reproves Berggren's theorem: the parent of
$(M,N) \ne (2,1)$ is $(M-2N,N)$ if $M>3N$, $(N,M-2N)$ if $2N<M\le3N$, and $(N,2N-M)$ if
$M \le 2N$.

\begin{theorem}[The outer moves are parabolic]\label{thm:par}
$\dfrac1{1-B_1(t)} = \dfrac1{1-t}+1$ and $\dfrac1{B_3(t)} = \dfrac1t+2$; hence
$B_1^k(t) = 1 - \frac{1-t}{1+k(1-t)} \to 1$ and $B_3^k(t) = \frac{t}{1+2kt} \to 0$ with
$k(1-B_1^k(t)) \to 1$ and $k B_3^k(t) \to \tfrac12$.
\end{theorem}

Moreover $B_1$ preserves $m-n$ and $B_3$ preserves $n$, which by Theorem~\ref{thm:line} are the
charges at the ideal points $1$ and $0$; in closed form
$B_1^k(n+u,n) = (n+(k+1)u,\ n+ku)$ and $B_3^k(m,n) = (m+2kn,\ n)$. So the $B_1$-orbits are the
rays of the $1$-star and the $B_3$-orbits the rays of the $0$-star.

\begin{theorem}[The middle move is hyperbolic]\label{thm:hypmove}
$B_2$ fixes the irrational silver slope $t_\star = \sqrt2-1$, and
$|B_2(s)-B_2(t)| = |s-t|/((2+s)(2+t)) \le |s-t|/4$ for $s,t \ge 0$; hence
$|B_2^k(t)-t_\star| \le 4^{-k}|t-t_\star|$.
\end{theorem}

\begin{theorem}[Step-length trichotomy]\label{thm:tricho}
Along a fan ray the step lengths tend to $0$ (Theorem~\ref{thm:steps0}). Along the Pell spine
$\mu_k = B_2^k(2,1) = (2,1),(5,2),(12,5),(29,12),\dots$ the cross products are $\pm1$ and the
ratios $r_k = m_{k+1}/m_k$ satisfy $r_{k+1} = 2+1/r_k \to 1+\sqrt2$, so by
Theorem~\ref{thm:twonode}
\[
  \cosh d(\mu_k,\mu_{k+1}) = \tfrac12\big(r_k+r_k^{-1}\big) + \frac1{2m_km_{k+1}}
  \longrightarrow \cosh\log(1+\sqrt2),
\]
and the spine steps converge to $\log(1+\sqrt2) = 0.881373\ldots$, the translation length of
the corresponding hyperbolic isometry.
\end{theorem}

The visual dichotomy --- fans gliding tangentially into the boundary versus one ray marching
away at constant speed --- is exactly the dichotomy between parabolic and hyperbolic
isometries, and it is consistent with Theorem~\ref{thm:irr}: the spine's limit $\sqrt2-1$ is
irrational, so no fan can form there.

\section{Collisions, factorisation, and a no-free-lunch theorem}

\begin{theorem}[Euler's two-representation method]\label{thm:euler}
If $N$ is odd and $N = a^2+b^2 = c^2+d^2$ with both representations primitive and
$\{a,b\}\ne\{c,d\}$, then $\gcd(N,ac+bd)\cdot\gcd(N,ad+bc) = N$, both factors being strictly
between $1$ and $N$.
\end{theorem}

\begin{proof}[Proof sketch]
$(ac+bd)(ad+bc) = (a^2+b^2)cd + (c^2+d^2)ab = N(ab+cd)$, so $N$ divides the product. With
$g = \gcd(N,ac+bd)$, $h = \gcd(N,ad+bc)$, a common prime of $g$ and $h$ would divide
$(a+b)(c+d)$ and $(a-b)(c-d)$, contradicting primitivity and oddness; so $\gcd(g,h)=1$,
$gh \mid N$ and $N \mid gh$.
\end{proof}

\begin{definition}
A \emph{collision} is a pair of distinct Euclid seeds with the same hypotenuse
$N = m_1^2+n_1^2 = m_2^2+n_2^2$; its \emph{pivot} is $P = m_1m_2+n_1n_2$ and its \emph{divisor}
$g = \gcd(N,P)$.
\end{definition}

\begin{example}
$65 = 8^2+1^2 = 7^2+4^2$; $P = 60$, $g = \gcd(65,60)=5$, complementary factor
$\gcd(65,39)=13$.
\end{example}

\begin{theorem}[Collisions at every scale]
For every $j \ge 0$ the pairs $(20j+9,\,10j+2)$ and $(20j+7,\,10j+6)$ are Euclid seeds with
common hypotenuse $N = 500j^2+400j+85$, and the extracted divisor is $5$.
\end{theorem}

\begin{theorem}[Colliding nodes are radially close]\label{thm:radclose}
Two seeds with the same hypotenuse $N$ have radii differing by at most $2\log2$
(Theorem~\ref{thm:traj}).
\end{theorem}

\begin{theorem}[Exact collision distance]\label{thm:colldist}
For a collision,
$\cosh d(z_1,z_2) = 1 + \dfrac{(N^2-P^2)+(m_1-m_2)^2}{2m_1m_2}$.
\end{theorem}

\begin{proof}
Theorem~\ref{thm:twonode} plus the Brahmagupta--Fibonacci identity
$N^2 = (m_1^2+n_1^2)(m_2^2+n_2^2) = P^2 + (n_1m_2-n_2m_1)^2$.
\end{proof}

\begin{theorem}[Two-sided law]\label{thm:twosided}
With the pivot deficit $D = N-P$, \ $\tfrac D2 \le \cosh d(z_1,z_2) - 1 \le 2D+2$.
\end{theorem}

\begin{theorem}[The divisor pushes the witnesses apart]\label{thm:push}
$\cosh d(z_1,z_2) \ge 1 + g/2$, hence $d(z_1,z_2) \ge \log g - \log 2$. If moreover
$N \le g^2$, then $d(z_1,z_2) \ge \tfrac12\log N - \log 2$.
\end{theorem}

\begin{proof}
$g \mid N$ and $g \mid P$ with $P<N$, so $g \mid D$ and $D \ge g$; apply
Theorem~\ref{thm:twosided} and $\cosh x \le e^x$.
\end{proof}

\begin{theorem}[Circle theorem and volume growth]\label{thm:ball}
A node lies within hyperbolic distance $R$ of $i$ iff
$(m-\cosh R)^2 + n^2 \le \sinh^2 R$, and the number of such nodes is $\Theta(e^{2R})$.
\end{theorem}

\begin{proof}[Proof sketch]
The condition is Theorem~\ref{thm:radial} after completing the square. Upper bound: $d \le R$
forces $c \le e^{2R}$, hence $m,n \le e^R$. Lower bound: sieve the box
$\{m \text{ even},\,2K<m\le4K\}\times\{n \text{ odd},\,1\le n\le 2K\}$, whose $K^2$ pairs
already have the right parity and ordering; discarding those with a common odd divisor
$d \ge 3$ leaves at least $K^2/4$ seeds for large $K$, all within radius $\log K + 2$.
\end{proof}

\begin{theorem}[No geodesic shortcut to factoring]\label{thm:nfl}
Let $N$ be odd with two primitive representations as a sum of two squares. The smallest ball
about $i$ guaranteed to contain both corresponding nodes has radius
$R \approx \tfrac12\log N + \log2$, and hence contains $\Theta(e^{2R}) = \Theta(N)$ nodes.
\end{theorem}

The geodesic to a collision is short --- length $\tfrac12\log N + O(1)$ --- but the number of
candidate endpoints at that radius is linear in $N$: the hyperbolic metric compresses the
search space and the search target by the same exponential factor. Theorem~\ref{thm:push}
closes the remaining loophole: even given one witness, the other is far away precisely when the
collision is informative. Trial enumeration in $O(\sqrt N)$ remains optimal among these
strategies. For a discrete path $z_0,\dots,z_k$ with energy $E = \sum_j d(z_j,z_{j+1})^2$,
Cauchy--Schwarz gives $E \ge d(z_0,z_k)^2/k$, so minimising energy rewards \emph{long} paths,
the opposite of what a search wants.

\section{Algorithms}

\begin{algorithmx}[Star census at a rational]
Input: coprime $p<q$, a charge bound $K$, a node bound $B$.
(1) Compute $x,y$ with $qx-py=1$ by the extended Euclidean algorithm, $O(\log q)$.
(2) Set $\gap = 2$ if $p,q$ are both odd, else $1$; the admissible charges are
$k \equiv 1 \pmod{\gap}$ with $|k| \le K$.
(3) For each admissible $k$, iterate over $A$, form $(m,n) = (qA+yk,\ pA+xk)$, and keep those
with $0<n<m\le B$, $\gcd(A,k)=1$ and $m+n$ odd; by Theorem~\ref{thm:copray} the coprimality
test is on $(A,k)$ alone.
(4) Report the width $\arsinh(|k|/q)$ and the per-period count of
Theorem~\ref{thm:bright}. Cost $O(K B/q)$ operations.
\end{algorithmx}

\begin{algorithmx}[Node geometry]
Input a seed $(m,n)$; output $c = m^2+n^2$, the radius $\arcosh((c+1)/(2m))$, and for each
rational of interest the charge $qn-pm$, the line parameter $k/q$, the width $\arsinh(|k|/q)$
and the resolution $\delta(p/q)$. Constant time per rational.
\end{algorithmx}

\begin{algorithmx}[Ray walk]
Given a seed and a rational with charge $k$, list the further nodes $(m+2tq,\ n+2tp)$ with the
exact step lengths of Theorem~\ref{thm:cross}. For $|k|=1$ every $t$ works
(Theorem~\ref{thm:unit}); otherwise sieve by $\gcd(A,k)=1$.
\end{algorithmx}

\begin{algorithmx}[Visible-star ranking]
Given $\varepsilon>0$, enumerate $q \le 2/\varepsilon$ and coprime $p \le q$, compute
$\delta(p/q)$ and keep those with $\delta \ge \varepsilon$; finiteness is
Theorem~\ref{thm:finite} and the output for $\varepsilon = 2/5$ is Theorem~\ref{thm:visible}.
\end{algorithmx}

\begin{algorithmx}[Ball enumeration]
Given $R$, loop over integer points of the Euclidean disc
$(m-\cosh R)^2+n^2 \le \sinh^2 R$ inside the cone $0<n<m$, testing coprimality and parity. Cost
$O(e^{2R}\log)$, versus $O(e^{4R})$ for a naive box scan.
\end{algorithmx}

\begin{algorithmx}[Collision factoring]
Given odd $N$, test each $m$ with $\sqrt{N/2}<m\le\sqrt N$ for $N-m^2$ a perfect square and
$(m,n)$ a seed; from two hits return $\gcd(N,m_1m_2+n_1n_2)$ and $\gcd(N,m_1n_2+n_1m_2)$. Cost
$O(\sqrt N)$; by Theorem~\ref{thm:nfl} no hyperbolic search improves on it.
\end{algorithmx}

\section{Discussion}

The results assemble into one statement: the star map of the Berggren tree is completely
explicit, and every feature of it is a theorem. \emph{Where the stars are:} at the rationals
and only there (Theorem~\ref{thm:irr}). \emph{Which rays exist:} all integer charges if $p+q$
is odd, only the odd ones if $p,q$ are both odd, with the central geodesic populated iff $p+q$
is odd and then by the single node $(q,p)$ (Theorems~\ref{thm:central}, \ref{thm:spectrum}).
\emph{How sharp a fan is:} resolution $\delta(p/q) = \gap(p,q)/q$, attained, giving the exact
visible list at threshold $2/5$ and a finite hierarchy at every threshold
(Theorems~\ref{thm:res}--\ref{thm:finite}). \emph{How bright a ray is:} $\varphi(k)$ or
$2\varphi(k)$ nodes per window of $2k$ ray parameters, because in ray coordinates both defining
conditions of a seed collapse to $\gcd(A,k)=1$ plus at most one parity class
(Theorem~\ref{thm:bright}). \emph{Why the rays look like lines:} their steps tend to zero and
they converge to their tips, the signature of parabolic dynamics, whereas the one exceptional
ray has steps converging to $\log(1+\sqrt2)$ (Theorem~\ref{thm:tricho}). \emph{What it is not
good for:} factoring (Theorems~\ref{thm:push}, \ref{thm:nfl}).

Two structural remarks. Almost every quantity here is exactly computable, because the
embedding is arithmetically transparent: $\Ima z = 1/m$ and $\Rea z = n/m$ are the seed
coordinates in disguise, so hyperbolic invariants become rational functions of $m$ and $n$, and
the single transcendental $\arcosh$ is removed by monotonicity. And the parity law is the one
genuinely arithmetic input, responsible for the only asymmetry in the picture: the eye is
seeing a trade-off between angular spacing and per-ray density, decided entirely by
$p+q \bmod 2$.

\section{Future directions}

\begin{conjecture}[Vanishing width at irrationals]
For every irrational $\alpha \in (0,1)$,
$\inf\{d_\HH(z(m,n),\gamma_\alpha) : (m,n)\ \text{a Euclid seed}\} = 0$, even though no
positive-width hypercycle over $\alpha$ contains more than one node
(Theorem~\ref{thm:irr}).
\end{conjecture}

The mechanism should be continued fractions: a seed close to $\gamma_\alpha$ is a convergent
$p_j/q_j$ of $\alpha$ of the right parity, since $|q_j\alpha - p_j| < 1/q_{j+1}$ makes the
charge-like quantity $q_jn - p_jm$ small; and among any two consecutive convergents at least
one has $p_j+q_j$ odd, because $p_{j+1}q_j - p_jq_{j+1} = \pm1$ forbids both from being
even-even and forces the parity vector to cycle through $(0,1),(1,0),(1,1)$. The B\'ezout
realisation of Theorem~\ref{thm:realise} supplies genuine seeds on any admissible ray, so the
missing ingredient is the convergent-parity lemma. Falsifiable by an irrational with a
deliberately chosen parity pattern together with a certified positive lower bound.

\begin{conjecture}[Exact volume asymptotics]
$\#\{\text{nodes within distance } R\} = \frac{\pi+2}{4\pi^2}e^{2R} + O(e^{3R/2})$, with
leading constant $0.13023806\ldots$
\end{conjecture}

By Theorem~\ref{thm:ball} this is a Gauss circle problem in the seed cone with a
coprimality-and-parity sieve: density $\frac6{\pi^2}\cdot\frac23 = \frac4{\pi^2}$, area factor
$\frac\pi4+\frac12$, and $\cosh^2 R \sim e^{2R}/4$. Direct enumeration gives ratios
$0.12890, 0.13016, 0.13012, 0.13020, 0.13024, 0.13024$ at $R = 3,\dots,8$.

\begin{conjecture}[Ces\`aro step statistics]
For an infinite word $w \in \{1,2,3\}^\NN$ let $d_k$ be the step length between consecutive
nodes of the corresponding path from the root. The Ces\`aro means
$\frac1K\sum_{k<K}d_k$ converge for every word, with set of limit values exactly
$[0,\log(1+\sqrt2)]$, the endpoints attained only by $1^\infty/3^\infty$ and $2^\infty$.
\end{conjecture}

Further open questions: do the nodes with hypotenuse in $[N,2N]$ equidistribute on the
corresponding annulus with respect to hyperbolic area? Which congruence subgroup of
$\mathrm{PGL}_2(\ZZ)$ do the three moves generate, and does the quantisation asymmetry appear
as a cusp width? Can the collision radius of Theorem~\ref{thm:radclose} be sharpened to match
the lower bound of Theorem~\ref{thm:twosided}? And is there a correctly \emph{weighted}
continued-fraction law for depth in the tree --- the unweighted one fails, since the right
spine $(2k+2,1)$ has depth $k$ and partial-quotient sum $2k+2$ while the left spine
$(k+2,k+1)$ has depth $k$ and sum $k+2$?

