"""Totient brightness census of a star ray."""

from math import gcd
from typing import Tuple


def totient(k: int) -> int:
    """Euler's totient function."""
    result, rest, d = k, k, 2
    while d * d <= rest:
        if rest % d == 0:
            while rest % d == 0:
                rest //= d
            result -= result // d
        d += 1
    if rest > 1:
        result -= result // rest
    return result


def bezout(p: int, q: int) -> Tuple[int, int]:
    old_r, r = q, p
    old_a, a = 1, 0
    old_b, b = 0, 1
    while r != 0:
        quo = old_r // r
        old_r, r = r, old_r - quo * r
        old_a, a = a, old_a - quo * a
        old_b, b = b, old_b - quo * b
    if old_r != 1:
        raise ValueError("p and q must be coprime")
    return old_a, -old_b


def predicted_census(p: int, q: int, k: int) -> int:
    """The brightness law: nodes among 2k consecutive ray parameters."""
    both_odd = (p % 2 == 1 and q % 2 == 1)
    if both_odd and k % 2 == 0:
        return 0                      # the ray is empty: quantisation
    if both_odd or k % 2 == 0:
        return 2 * totient(k)         # full brightness
    return totient(k)                 # mixed regime: half brightness


def scanned_census(p: int, q: int, k: int, offset: int = 0) -> int:
    """Direct lattice scan of the window [offset, offset + 2k) of ray parameters."""
    x, y = bezout(p, q)
    hits = 0
    for big_a in range(offset, offset + 2 * k):
        m, n = q * big_a + y * k, p * big_a + x * k
        if gcd(m, n) == 1 and (m + n) % 2 != 0:
            hits += 1
    return hits


def ray_density(p: int, q: int, k: int) -> float:
    """Linear density of Berggren nodes along the ray of charge k at p/q."""
    return predicted_census(p, q, k) / (2 * k)

"""Hyperbolic ball enumeration via the circle theorem."""

from math import cosh, gcd, sinh, sqrt
from typing import Iterator, Tuple


def is_seed(m: int, n: int) -> bool:
    return 0 < n < m and gcd(m, n) == 1 and (m + n) % 2 == 1


def ball_nodes(radius: float) -> Iterator[Tuple[int, int]]:
    """Yield every Euclid seed whose node lies within hyperbolic distance R of i.

    The circle theorem turns the transcendental condition
        arcosh((m^2 + n^2 + 1)/(2m)) <= R
    into the Euclidean disc condition
        (m - cosh R)^2 + n^2 <= sinh^2 R,
    so the enumeration is a lattice-point scan of a disc of radius sinh R centred
    at (cosh R, 0), intersected with the seed cone 0 < n < m.
    """
    c, s = cosh(radius), sinh(radius)
    for m in range(1, int(c + s) + 1):
        slack = s * s - (m - c) ** 2
        if slack < 0.0:
            continue
        nmax = min(m - 1, int(sqrt(slack)))
        for n in range(1, nmax + 1):
            if is_seed(m, n):
                yield (m, n)


def ball_count(radius: float) -> int:
    """The number of nodes within distance R of i; grows like Theta(e^{2R})."""
    return sum(1 for _ in ball_nodes(radius))
